/// Lightweight bilingual copy table. Keeping a single indexed map avoids
///generated files and makes adding a third language a local change.
class AppStrings {
  AppStrings(this.state);

  final LocaleState state;

  static const supportedLocales = [Locale('ar'), Locale('en')];

  static AppStrings of(BuildContext context) =>
      AppStrings(context.watch<LocaleCubit>().state);

  bool get isArabic => state.isArabic;
  TextDirection get direction => state.textDirection;
  Locale get locale => state.locale;

  String t(String key) {
    final entry = _copy[key];
    if (entry == null) return key;
    return isArabic ? entry[0] : entry[1];
  }

  String money(num value) {
    final text = value.toStringAsFixed(value % 1 == 0 ? 0 : 2);
    return isArabic ? '$text ج.م' : 'EGP $text';
  }

